const msg = $json.message || {};
const chatInput = (msg.text || '').trim();
const chatId = msg.chat && msg.chat.id ? msg.chat.id : '';

const hasVoice = !!msg.voice;
let voiceFileId = '';

if (msg.voice && msg.voice.file_id) {
  voiceFileId = msg.voice.file_id;
}

const key = 876;

return [{
  json: {
    chatId,
    chatInput,
    hasVoice,
    voiceFileId,
    key,
    original: $json
  }
}];

