const chatId = $node["Telegram Trigger1"].json?.message?.chat?.id || null;
if (!chatId) {
  throw new Error("chatId not found in Telegram Trigger node");
}

const rooms = $node["Get Rooms"].json?.content || [];

// Format giá ngắn gọn
const formatPrice = (price) => {
  if (price >= 1000000) return `${(price/1000000).toFixed(1)}M`;
  if (price >= 1000) return `${(price/1000).toFixed(0)}K`;
  return price.toString();
};

// Limit số phòng hiển thị (tránh quá dài)
const maxRooms = 20;
const displayRooms = rooms.slice(0, maxRooms);

let roomText = "🏠 **DANH SÁCH PHÒNG**\n\n";

if (displayRooms.length > 0) {
  roomText += displayRooms.map((room, idx) => {
    // Rút gọn amenities
    const amenities = [];
    if (room.wifi) amenities.push("📶");
    if (room.airConditioner) amenities.push("❄️");
    if (room.tv) amenities.push("📺");
    if (room.kitchen) amenities.push("🍳");

    return `**${idx + 1}. ${room.name}**\n` +
           `💰 ${formatPrice(room.price)} VND • 🛏️ ${room.bedRoom}PN-${room.bed}G\n` +
           `${amenities.join("")} • ${room.location ? room.location.province : "N/A"}`;
  }).join("\n\n");

  if (rooms.length > maxRooms) {
    roomText += `\n\n... và ${rooms.length - maxRooms} phòng khác`;
  }

} else {
  roomText += "❌ Không có phòng nào.";
}

roomText += `\n\n💡 Gõ "Phòng [tên]" để xem chi tiết`;

return [{
  json: {
    chatId,
    text: roomText
  }
}];

const chatId = $node["Telegram Trigger1"].json?.message?.chat?.id || null;
if (!chatId) {
  throw new Error("chatId not found in Telegram Trigger node");
}

const locations = $node["Get Locations"].json?.content || [];

if (locations.length === 0) {
  return [{
    json: {
      chatId,
      text: "❌ Không tìm thấy địa điểm nào.",
      parse_mode: "Markdown"
    }
  }];
}

const maxLocations = 15;
const displayLocations = locations.slice(0, maxLocations);

// Tìm location đầu tiên có ảnh để làm ảnh đại diện
const locationWithImage = displayLocations.find(loc => loc.image && loc.image.trim() !== "");

// Tạo text content
let locationText = `📍 **DANH SÁCH ĐỊA ĐIỂM KHẢ DỤNG**\n\n`;
locationText += `Tìm thấy ${locations.length} địa điểm:\n\n`;

locationText += displayLocations.map((location, idx) => {
  const hasImage = location.image && location.image.trim() !== "" ? "🖼️" : "🏞️";

  return `${hasImage} **${idx + 1}. ${location.name}**\n` +
         `   🏛️ ${location.province}, ${location.country}`;
}).join("\n\n");

locationText += `\n\n💡 Gõ "Tìm phòng ở [tên địa điểm]" để xem chi tiết`;

// Gửi với ảnh đại diện nếu có
if (locationWithImage) {
  return [{
    json: {
      chatId,
      photo: locationWithImage.image.startsWith('http') ? locationWithImage.image : `https://booking-api.hau.io.vn${locationWithImage.image}`,
      caption: locationText,
      parse_mode: "Markdown"
    }
  }];
} else {
  return [{
    json: {
      chatId,
      text: locationText
    }
  }];
}

const chatId = $node["Telegram Trigger1"].json?.message?.chat?.id || null;
if (!chatId) {
throw new Error("chatId not found in Telegram Trigger node");
}

return [{
