const chatId = $node["Telegram Trigger1"].json?.message?.chat?.id || null;

if (!chatId) {
  throw new Error("chatId not found in Telegram Trigger node");
}

const comments = $node["Get Reviews"].json?.content || [];

// Format comments
let commentText = "💬 *Danh sách bình luận:*\n\n";
if (comments.length > 0) {
  commentText += comments.map((c, idx) => {
    const userName = c.user?.name || "Ẩn danh";
    const rating = "⭐".repeat(c.rating) || "Chưa đánh giá";
    const date = new Date(c.createdAt).toLocaleDateString("vi-VN");
    return `*${idx + 1}. ${userName}* (${date})\n${rating}\n"${c.content}"\n`;
  }).join("\n");
} else {
  commentText += "Chưa có bình luận nào.";
}

return [{
  json: {
    chatId,
    commentText,
  }
}];

