const chatId = $node["Telegram Trigger1"].json?.message?.chat?.id || null;
if (!chatId) {
  throw new Error("chatId not found in Telegram Trigger node");
}

// Lấy thông tin phòng từ AI Agent
const aiOutput = $node["AI Agent1"].json?.output || "";

// Parse JSON từ output (vì AI trả về trong code block)
let roomData;
try {
  // Extract JSON từ markdown code block
  const jsonMatch = aiOutput.match(/```json\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    roomData = JSON.parse(jsonMatch[1]);
  } else {
    roomData = JSON.parse(aiOutput);
  }
} catch (error) {
  return [{
    json: {
      chatId,
      text: "Lỗi xử lý dữ liệu phòng. Vui lòng thử lại."
    }
  }];
}

// Kiểm tra status
if (roomData.status !== "found") {
  return [{
    json: {
      chatId,
      text: roomData.message || "Không tìm thấy thông tin phòng."
    }
  }];
}

const room = roomData.room;
const location = room.location;

// Format giá tiền
const formatPrice = (price) => {
  return new Intl.NumberFormat('vi-VN', {
    style: 'currency',
    currency: 'VND'
  }).format(price);
};

// Format amenities
const amenities = [];
if (room.washingMachine) amenities.push("🧺 Máy giặt");
if (room.balcony) amenities.push("🏢 Ban công");
if (room.tv) amenities.push("📺 TV");
if (room.airConditioner) amenities.push("❄️ Điều hòa");
if (room.wifi) amenities.push("📶 Wifi");
if (room.kitchen) amenities.push("🍳 Nhà bếp");
if (room.parking) amenities.push("🚗 Chỗ đậu xe");
if (room.swimmingPool) amenities.push("🏊 Hồ bơi");

const amenitiesText = amenities.length > 0 ? amenities.join("\n") : "Không có tiện ích đặc biệt";

// Tạo message hiển thị
const message = `🏨 **THÔNG TIN PHÒNG**

📌 **Tên phòng:** ${room.name}
🆔 **ID:** ${room.id}

🛏️ **Thông tin phòng:**
- Phòng ngủ: ${room.bedRoom}
- Giường: ${room.bed} 
- Phòng tắm: ${room.bathRoom}

💰 **Giá:** ${formatPrice(room.price)}/đêm

📝 **Mô tả:**
${room.description}

🎯 **Tiện ích:**
${amenitiesText}

📍 **Địa điểm:**
- Tên: ${location.name}
- Tỉnh/Thành: ${location.province}
- Quốc gia: ${location.country}

🕐 **Thời gian:**
- Tạo: ${new Date(room.createdAt).toLocaleString('vi-VN')}
- Cập nhật: ${new Date(room.updatedAt).toLocaleString('vi-VN')}`;

// Kiểm tra có ảnh hay không và trả về response phù hợp
if (room.picture && room.picture.trim() !== "") {
  // Có ảnh - gửi photo với caption
  return [{
    json: {
      chatId,
      photo: room.picture.startsWith('http') ? room.picture : `https://booking-api.hau.io.vn${room.picture}`,
      caption: message,
      parse_mode: "Markdown"
    }
  }];
} else {
  // Không có ảnh - chỉ gửi text
  return [{
    json: {
      chatId,
      text: message,
      parse_mode: "Markdown"
    }
  }];
}

