const chatInput = $node["Normalize Text1"].json?.chatInput || null;

if (!chatInput) {
  throw new Error("chatInput not found in Normalize Text1 node");
}

// Tách từng dòng
const lines = chatInput.split("\n").map(l => l.trim()).filter(Boolean);

let booking = {};

// Mapping từ text sang field
lines.forEach(line => {
  if (line.startsWith("Room ID:")) {
    booking.roomId = line.replace("Room ID:", "").trim();
  }
  if (line.startsWith("User ID:")) {
    booking.userId = line.replace("User ID:", "").trim();
  }
  if (line.startsWith("Số lượng khách:")) {
    booking.guestCount = parseInt(line.replace("Số lượng khách:", "").trim(), 10);
  }
  if (line.startsWith("Ngày nhận phòng:")) {
    booking.checkInDate = new Date(line.replace("Ngày nhận phòng:", "").trim()).toISOString();
  }
  if (line.startsWith("Ngày trả phòng:")) {
    booking.checkOutDate = new Date(line.replace("Ngày trả phòng:", "").trim()).toISOString();
  }
});

// Trả về JSON cho HTTP Request Node
return [{
  json: booking
}];

